import json,glob,os,collections,datetime as dt
D='~/.claude/projects/multicode/73c9b302-fd61-4f66-9218-f3caf0a4266d/subagents/workflows'
S=glob.glob('~/.claude/projects/*/73c9b302-fd61-4f66-9218-f3caf0a4266d/workflows/scripts/*.js')
names={}
for s in S:
    b=os.path.basename(s)
    if '-wf_' in b: names['wf_'+b.split('-wf_')[1][:-3]]=b.split('-wf_')[0]
def ts(x): return dt.datetime.fromisoformat(x.replace('Z','+00:00'))
tot=collections.Counter(); rows=[]
for w in sorted(os.listdir(D)):
    ags=glob.glob(f'{D}/{w}/agent-*.jsonl')
    day=[];models=collections.Counter();efforts=collections.Counter();t0=None;t1=None;cached=0
    for a in ags:
        first=last=None;model=None;eff=None
        for line in open(a,errors='ignore'):
            try:j=json.loads(line)
            except:continue
            t=j.get('timestamp')
            if t:
                first=first or t;last=t
            m=j.get('message') or {}
            if isinstance(m,dict) and m.get('model') and not model: model=m['model']
        if not first or not first.startswith('2026-11-02'):continue
        try: meta=json.load(open(a[:-6]+'.meta.json'))
        except: meta={}
        mm=model or meta.get('model'); models[mm]+=1
        day.append(a); f,l=ts(first),ts(last)
        t0=min(t0,f) if t0 else f; t1=max(t1,l) if t1 else l
    if not day: continue
    jr=f'{D}/{w}/journal.jsonl'
    if os.path.exists(jr):
        st=[json.loads(x) for x in open(jr) if x.strip()]
    rows.append((t0,w,names.get(w,'?'),len(day),dict(models),(t1-t0).total_seconds()/60))
    tot.update(models)
for r in sorted(rows): print(r[0].strftime('%H:%M'),r[1],r[2],r[3],r[4],round(r[5],1))
print('workflows',len(rows),'agents',sum(r[3] for r in rows),dict(tot))
print('sum min',round(sum(r[5] for r in rows),1))
EOF
